def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Centers lie on the repeated seven-cell tile lattice.
    pts={}
    for r in range(3,h,7):
      for c in range(3,w,7):
        v=grid[r][c]
        if v not in (0,4): pts.setdefault(v,[]).append((r,c))
    dominant=max(pts, key=lambda v:len(pts[v]))
    for v,cells in pts.items():
      if v==dominant: continue
      for i,(r,c) in enumerate(cells):
       for rr,cc in cells[i+1:]:
        if r==rr or c==cc:
         if r==rr:
          for dy in (-1,0,1):
           for x in range(min(c,cc)-1,max(c,cc)+2):
            y=r+dy
            if 0<=y<h and 0<=x<w and out[y][x]==0: out[y][x]=v
         else:
          for dx in (-1,0,1):
           for y in range(min(r,rr)-1,max(r,rr)+2):
            x=c+dx
            if 0<=y<h and 0<=x<w and out[y][x]==0: out[y][x]=v
    return out
